node -e "
const toRad = d => d * Math.PI / 180;

// Current location: San Francisco, CA
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 (approximate coordinates for South End area)
const lat2 = 42.3388, lon2 = -71.0765;

// Haversine formula
const R = 6371; // Earth radius in km
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const distKm = R * c;
const distMiles = distKm * 0.621371;

console.log('=== Distance Calculation ===');
console.log('');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('       (≈ 42.3388, -71.0765)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm.toLocaleString('en-US', {maximumFractionDigits: 2}) + ' km');
console.log('  ' + distMiles.toLocaleString('en-US', {maximumFractionDigits: 2}) + ' miles');
"
